macro.command:
// Shapechange — add at-will version of the spell to the polymorphed creature
// so the caster can use their action to assume a different form during the duration.
const transformedActors = workflow.transformedActors ?? [];
if (!transformedActors.length) return;
const spellData = item.toObject();
// Set preparation to at-will so it doesn't consume spell slots
spellData.system.preparation = { mode: "atwill", prepared: true };
// Remove material cost requirement
spellData.system.materials = { value: "", consumed: false, cost: 0, supply: 0 };
// Remove concentration (the original caster maintains concentration)
spellData.system.properties = spellData.system.properties.filter(p => p !== "concentration");
// Disable spell slot consumption and concentration on all activities
for (const [id, act] of Object.entries(spellData.system.activities)) {
  act.consumption = { targets: [], scaling: { allowed: false, max: "" }, spellSlot: false };
  if (act.duration) act.duration.concentration = false;
}
// Generate a new ID to avoid conflicts
spellData._id = foundry.utils.randomID();
// Mark as at-will transform so it can be identified and cleaned up
foundry.utils.setProperty(spellData, "flags.midi-qol.atWillTransform", true);
for (const polyActor of transformedActors) {
  await polyActor.createEmbeddedDocuments("Item", [spellData]);
}
